#!/usr/bin/env python3
"""Generate densitytosz_validation.md and experiment_summary.md from the saved results (no FAC, no calculations).

All numbers in the tables come from results/*.json and results/*.csv; the narrative around them is fixed text that
states what the numbers show.  Re-run after any change in the results.

Usage: python write_reports.py [--results-dir DIR]
"""

from __future__ import annotations

import argparse
import csv
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / "shared"))
import analysis_support as an      # noqa: E402


def e(x, d=1):
    return "—" if x is None or x != x else f"{x:.{d}e}"


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--results-dir", type=Path, default=HERE / "results")
    res = ap.parse_args().results_dir.resolve()
    pv = json.loads((res / "potential_validation_summary.json").read_text())
    first = json.loads((res / "potential_validation_summary_first_run.json").read_text())
    man = json.loads((res / "experiment_manifest.json").read_text())
    num = json.loads((res / "analysis_numbers.json").read_text())
    foc = list(csv.DictReader(open(res / "first_order_check" / "first_order_check.csv")))
    ipc = list(csv.DictReader(open(res / "ip_comparison.csv")))
    T = pv["tests"]

    # ------------------------------------------------------------------ densitytosz_validation.md
    tb = [[k.replace("@mu=", ", mu="), e(v["max_abs_over_scale"]), e(v["rms_over_scale"]), e(v["max_rel_bulk"]), e(v["max_rel_tail_resolved"]),
           e(v["ref_self_consistency_over_scale"], 0), e(v["jps_rel_err"], 0), "gated" if v["gated"] else "informational", "PASS" if v["pass"] else "FAIL"]
          for k, v in T["B_independent_integral"].items()]
    ta = [[k, "yes" if all(v.values()) else "NO", e(T["A_coulomb_limit"]["closed_form_coulomb"][k]["max_abs_over_scale"]),
           f"{T['A_coulomb_limit']['closed_form_coulomb'][k]['rV_at_r_max_fac']:.8f} / {T['A_coulomb_limit']['closed_form_coulomb'][k]['N_expected_from_FAC_convention']:g}",
           ", ".join(f"{s:.3f}" for s in T["A_coulomb_limit"]["continuity"][k]["loglog_slopes"])]
          for k, v in T["A_coulomb_limit"]["bit_identity"].items()]
    tg = []
    for k, v in T["B_grid_convergence"].items():
        tg.append([k.replace("@mu=", ", mu=")] + [f"{e(v[n]['screened'])} / {e(v[n]['coulomb_pristine'])}" for n in ("750", "1500", "3000", "6000")] + [f"{v['max_ratio_screened_to_coulomb']:.2f}"])
    tc = [[k.replace("@mu=", ", mu="), e(v["max_rel_dev_from_reference"]), e(v["median_log_slope"] + 0, 3) if False else f"{v['median_log_slope']:.6f}",
           f"{v['expected_log_slope']:.2f}", e(v["max_slope_error_resolved"]), "PASS" if v["pass"] else "FAIL"]
          for k, v in T["C_large_radius"].items() if "n_points" in v and "median_log_slope" in v]
    plateau = [[k.replace("no_coulomb_plateau_", "").replace("@mu=0.1", ""), f"{v['rV_at_r_max']:.2e}", f"{v['coulomb_plateau_N']:g}", "PASS" if v["pass"] else "FAIL"]
               for k, v in T["C_large_radius"].items() if k.startswith("no_coulomb")]
    d = T["D_numerical_stability"]
    fo = {(r["ion"], r["variant"], r["mu"]): r for r in foc}
    fo_rows = []
    for ion in dict.fromkeys(r["ion"] for r in foc):
        fo_rows.append([ion] + [f"{float(fo[(ion, v, m)]['deviation_percent']):+.2f}%" for v in "AB" for m in ("0.001", "0.003", "0.01")])

    val = ["# DensityToSZ(): source audit, derivation and potential-level validation", "",
           "Generated by `write_reports.py` from `potential_validation_summary.json`, `potential_validation.csv`, `first_order_check/` and "
           "`experiment_manifest.json`. The tested code is the real compiled `DensityToSZ()` from `libfac.a` of the experimental build "
           f"(FAC source `{man['variant_B']['fac_source_commit'][:10]}`, flags `{man['variant_B']['build_info'].get('cflags')}`, no workaround flag), "
           "called through the C harness `harness/densitytosz_harness.c` on FAC's own radial grid.", "",
           "## 1. Source audit (the source and the binary are the authority)", "",
           "Call path in the SCF (`faclib/radial.c`, `faclib/orbital.c`):", "",
           "```",
           "OptimizeRadial -> OptimizeILoop (each SCF iteration) -> SetPotential(acfg, iter)           radial.c",
           "  -> PotentialHX -> PotentialHX1                                                           radial.c",
           "       DensityToSZ(potential, potential->NPS, u, ue1, &jps0, 0)   [orbital.c, v2 kernel]    <- direct potential, every iteration",
           "       SetPotentialPS(...)           ZPS = Z(r)(1 - exp(-r/dps))  (nuclear Debye term)",
           "  PotentialHX: u = u0 - ue  (direct minus exchange), optional csi/ihx asymptotic-charge adjustment",
           "  SetPotential: U(r) = (u - Z - Vc r)/r = u/r ;  SetPotentialU ; SetPotentialVT: VT = Vc + U + ZPS/r",
           "```", "",
           "| question | answer from the source and the harness |", "|---|---|",
           "| density passed in | `potential->NPS` = sum over shells of `nq (P^2 + Q^2)`: the radial density with integral `D dr = N`. In Debye mode (`mps = 1`) all electrons are in this one density (`N = NC` in the potential header, e.g. 24 = 24 for Fe III); the second, valence-only call is skipped. The harness confirms the convention: `r V(r_max)` of the Coulomb path equals N to 3e-7 N (the quadrature floor). |",
           "| grid and quadrature | `rho = a r^q + b ln r` with unit index steps, `rad[0] = r_min ~ 4e-8 a0`, `rad[maxrp-1] ~ 1009 a0` (1500 points); integrals are cumulative cubic-spline quadratures in `rho` (`NewtonCotesIP`) of `D dr/drho`; the origin segment uses `D0 r0/3`. |",
           "| returned array | `z = r V_H(r)` (positive for a positive density, atomic units), `jps = int_{r0}^inf D exp(-mu t)/t dt` (matches the reference, 2e-7 relative, = the Coulomb-path quadrature floor). |",
           "| conversion to the effective potential | `u = z - zx` (direct minus exchange), `U = u/r` (the Coulomb `-Z/r` pieces cancel in `SetPotential`), added to `Vc` and `ZPS/r` in `SetPotentialVT`. |",
           "| same mu everywhere | `EEScreenMu() = 1/dps` when `radial:ee_screen = 1`, `mps = 1`, `dps > 0`; `GetYkDebye` (screened Slater integrals) calls the same `EEScreenMu()`, and the nuclear term uses the same `dps`. The harness reports `EEScreenMu = 0.1000000000000033` for the requested 0.1. |",
           "| gating, unscreened path | `mu > 0` selects the screened kernel; otherwise the original statements run verbatim. Bit-identical to the pristine upstream library (Test A). `ee_screen = 0` with the plasma on gives `EEScreenMu = 0` and the same Coulomb result. NaN, negative or infinite mu aborts. |",
           "| outer integral and tail | the screened integrals are accumulated in blocks of exponent span `mu dr <= 100` with scaled integrands, so nothing overflows; the outer integral starts from zero at the last grid point (density beyond `r_max` is neglected, as in the Coulomb path). |",
           "| used in every SCF iteration | yes: `DensityToSZ` runs inside `PotentialHX1` on each `SetPotential`, i.e. in every iteration; the A/B energies and the asymptotic charge (0 for B, N-1 for A) prove the orbitals respond to it. |",
           "| not screened | local exchange, Breit and QED terms. The `csi`/`ihx` block in `PotentialHX` (below) was written for a Coulomb tail. |", "",
           "## 2. Derivation (independent of FAC)", "",
           "With `w(r12) = exp(-mu r12)/r12` the angular integral over the direction of `r'` gives, exactly,",
           "`int dOmega' w / (4 pi) = [exp(-mu|r-r'|) - exp(-mu(r+r'))] / (2 mu r r')`, hence for a spherical density with `int D dr = N`",
           "", "`r V(r) = int_0^inf D(r') [exp(-mu|r-r'|) - exp(-mu(r+r'))] / (2 mu r') dr'`.",
           "", "For `r' < r` the kernel `[...]/(2 mu r')` equals `exp(-mu r) sinh(mu r')/(mu r')`; for `r' > r` it equals `exp(-mu r') sinh(mu r)/(mu r')`. Therefore",
           "", "`r V(r) = exp(-mu r) int_0^r D sinh(mu r')/(mu r') dr' + r [sinh(mu r)/(mu r)] int_r^inf D exp(-mu r')/r' dr'`,",
           "which is the expression of the task, and equals the `k = 0` Yukawa multipole `mu i_0(mu r<) k_0(mu r>)`. For `mu -> 0` it becomes `int_0^r D + r int_r^inf D/r'`. "
           "FAC's `E(x) = (1 - exp(-2x))/(2x) = exp(-x) sinh(x)/x` is the same function written without `sinh` (identity checked below), so `z = A~ + r E(mu r) B~` with `A~ = exp(-mu r) int D sinhc`, `B~ = exp(mu r) int D exp(-mu r')/r'`.", "",
           "Two reference evaluators, neither using FAC's integrator or grid: (1) exact closed forms for densities `sum c r^m exp(-beta r)` in 80-digit `decimal` arithmetic; "
           "(2) 16-point Gauss-Legendre quadrature of the direct-kernel form above in float64 (no multipole expansion, no sinh). "
           f"They agree with each other to <= {max(v['ref_self_consistency_over_scale'] for v in T['B_independent_integral'].values()):.0e} of the peak, so the references are valid.", "",
           "Test densities (normalised, `D = N (2a)^(2k+1)/(2k)! r^2k exp(-2ar)`): compact 1s-like (N=2, a=13), valence (N=6, k=2, a=1), diffuse (N=1, a=0.06, so `2a < mu` for mu >= 0.12), "
           "multishell Fe III-like (N=24). Tolerances were fixed before the first comparison (see `potential_validation.py` header).", "",
           "## 3. Test A: Coulomb limit", "",
           an.md_table(["density", "bit-identical to pristine upstream (plain, plasma+ee_screen off, variant A)", "Coulomb vs closed form (max abs / peak)", "rV(r_max) / N", "log-log slope of |rV(mu) - rV(0)| for mu = 1e-8..1e-4 (r <= 5)"], ta), "",
           "Bit-identity covers `rV`, `jps` and the whole array for four densities. The screened result approaches the Coulomb one linearly in mu (slope 1). "
           "The floor of 1e-7..4e-7 of the peak is FAC's own cumulative quadrature (identical in the pristine library).", "",
           "## 4. Test B: independent Yukawa integral (default 1500-point grid)", "",
           an.md_table(["case", "max abs / peak", "rms / peak", "max rel (bulk)", "max rel (tail, resolved)", "ref-vs-ref", "jps rel", "status", "result"], tb), "",
           f"Gated cases (mu = 1e-4, 0.01, 0.1, 0.25, 1) pass except where noted: "
           + "; ".join(f"`{x[:200]}`" for x in pv["failures"]) if pv["failures"] else "All gated cases pass.", "",
           "Residuals as a function of radius for every grid point at mu = 0.1 and 0.25 (and every 5th point otherwise) are in `potential_validation.csv` "
           "(columns r, D, rV_FAC, rV_closed_form, rV_direct_quadrature, residual_abs, residual_rel); plots `plots/07a_*`, `07b_*`.", "",
           "**The one remaining failure is not hidden:** diffuse density, mu = 0.25: the deep-tail relative error is 1.0047e-5 against the declared 1e-5, "
           "in the region where `rV` is below 1e-3 of its peak (absolute error there 1e-8 of the peak); it is the `2a < mu` case where `rV` decays like the density, "
           "not like `exp(-mu r)`. Diffuse at mu = 1 is outside the grid's resolution (mu dr up to 0.5 where the density lives) and was declared informational after the first run (R7).", "",
           "### Grid dependence (screened / pristine Coulomb residual, max abs over peak)", "",
           an.md_table(["case", "750", "1500", "3000", "6000", "max screened/Coulomb"], tg), "",
           "The residual does not shrink with more grid points, in the pristine Coulomb path either: a grid-independent floor of 1e-8..1e-7 of the peak is a property of the "
           "original integrator, and the screened result stays within 2.3x of it.", "",
           "## 5. Test C: large-radius behaviour", "",
           an.md_table(["case", "max rel dev from reference (beyond saturation)", "median d ln(rV)/dr", "expected -mu", "max slope error (resolved)", "result"], tc), "",
           "Beyond the density, `rV` falls exponentially with slope `-mu` to 1e-13, follows the reference to 1e-7..1e-8 down to values of 1e-100 and below, stays positive and finite, "
           "and shows no constant plateau, truncation, overflow or grid-boundary artefact. At `r_max = 1009` (mu = 0.1):", "",
           an.md_table(["density", "rV(r_max)", "Coulomb plateau N", "result"], plateau), "",
           "`NewtonCotesIP` boundary handling and the grid extent are sufficient for the screened outer integral: the outer integral is `exp(-mu r)` small beyond ~100/mu. "
           "Relative accuracy degrades only deep in the tail of the pathological diffuse density (error 1e-5 at 1e-17 of the peak, 26% at 1e-50), where no energy can be affected.", "",
           "## 6. Test D: numerical stability", "",
           f"* `E(x) = -expm1(-2x)/(2x)` equals `exp(-x) sinh(x)/x` (80-digit reference) to {d['E_of_x_max_rel_error_1e-12_to_5000']:.1e} relative for x from 1e-12 to 5000; `E(0) = 1` is explicit; "
           f"the source text of `_ee_E` was matched by regex: {d['source_ee_E_is_exp_minus_x_sinh_x_over_x']}.",
           "* mu = 5 (`mu r_max = 5000`) and mu = 1e-10 (nearly Coulomb): all outputs are finite for all four densities (no overflow or NaN).",
           "* The block-scaling constant (span 100) causes no visible error in the contributing region (Tests B, C).", "",
           "## 7. Test E: physical consistency", "",
           "* The screened direct potential is repulsive (positive) wherever representable and never exceeds the Coulomb one, for every density at mu = 0.1, 0.25, 1 (all PASS); "
           "far from the density it is a small fraction of the Coulomb value (e.g. 0.13 at the first grid point beyond 20 a0 for mu = 0.1).",
           "* One-electron Fe XXVI: no electron-electron direct contribution; with nuclear screening the energy shifts by +70.5484 eV (mu = 0.1) and +175.6213 eV (0.25), independent of mu_ee "
           "(identical for cases A/B and C/D), matching an independent Dirac-Yukawa solver to 5e-4 eV.",
           "* The screened Slater pathway stays active when the direct-potential modification is removed: the electron-electron screening effect on the Fe XVII energy is -120.5816 eV in the "
           "Coulomb-direct build (variant A) and -120.5824 eV in the screened build (B); nuclear-only runs are bit-identical in both builds (`results/physical_checks/`).", "",
           "## 8. Exact first-order Debye-Hückel check of the screened total energy (outside DensityToSZ, but decisive for interpretation)", "",
           "To first order `exp(-mu r)/r = 1/r - mu`, so for any normalised wavefunction `dE = mu (N Z - N(N-1)/2)` Hartree. Deviation of FAC's `E(mu) - E(0)` from it (%):", "",
           an.md_table(["ion", "A mu=0.001", "A 0.003", "A 0.01", "B mu=0.001", "B 0.003", "B 0.01"], fo_rows), "",
           "Variant A follows theory (second-order deviations); variant B falls short, increasingly with the electron number and the open 3d shell (-1.2% for Fe III at mu = 0.001). "
           "Setting `radial:csi = 0` removes the deficiency (Fe III: -0.02%). The `csi`/`ihx` block of `PotentialHX1` adjusts the potential towards the asymptotic charge N+ihx, a Coulomb-tail construct; "
           "it acts only where the screened Hartree potential still reaches N-1 (small mu): at mu = 0.1 and 0.25 `csi = 0` leaves the Fe II-IV energies unchanged "
           "(`results/csi_zero_diagnostic`). This is **not** an error of `DensityToSZ` (the potential-level tests pass); its origin inside the `csi` block is a lead, not a finding.", "",
           "## 9. Criteria revisions after the first run (kept transparent)", "",
           f"The first run (`potential_validation_summary_first_run.json`) failed {len(first['failures'])} checks. Inspection showed flaws in my tests, not in DensityToSZ: "
           "R1 the normalisation threshold (1e-9) was below FAC's own quadrature floor (use the declared 1e-6); R2 sup-norm continuity cannot be linear once `mu r_max >> 1` (use r <= 5 a0); "
           "R3 \"residual drops 4x when the grid is doubled\" fails for the pristine Coulomb path too (use screened <= 3x Coulomb floor); R4 \"no plateau\" demanded <1e-100 where "
           "`exp(-0.1*1009) ~ 1e-44` (use <1e-30 N); R5 positivity was tested where the double underflows to 0; R6 tail relative accuracy only where |ref| >= 2.2e-16 x peak; "
           "R7 diffuse at mu = 1 informational. The declared tolerances 1e-6 / 1e-5 were not changed, and the marginal diffuse mu = 0.25 failure stayed a failure.", "",
           "## Verdict", "",
           "`DensityToSZ()` implements the screened Yukawa Hartree potential correctly (closed form and independent quadrature agree to 1e-7..1e-8 of the peak on FAC's grid, "
           "bit-identical Coulomb path, exact `exp(-mu r)` decay with no artefact), with one pre-declared criterion marginally missed in the deep tail of an extreme density.", ""]
    (res / "densitytosz_validation.md").write_text("\n".join(val))

    # ------------------------------------------------------------------ experiment_summary.md
    B = {(r["ionization"], r["case"]): r for r in ipc}
    ip_rows = []
    for r in ipc:
        ip_rows.append([r["ionization"], r["mu"], r["IP_A_eV"][:8] or "—", r["IP_B_eV"][:8], r["ip_paper_eV"], r["err_vs_paper_B_eV"][:7], r["rel_err_vs_paper_B_percent"][:6],
                        r["ip_nist_eV"] or "—", r["err_vs_nist_B_eV"][:6] or "—", r["shift_B_eV"][:7] or "—", r["shift_paper_eV"], r["shift_err_B_eV"][:6] or "—"])
    lad0 = num["ladder_csi0"]
    ladd = num["ladder_default_csi"]
    ph = num["physical_checks"]
    maxdirect = max(abs(x["dE_direct_potential"]) for x in ph)
    summ = ["# DensityToSZ A/B experiment: effect of the screened SCF direct potential on Fe II / Fe III / Fe IV", "",
            "*Reduced reference-configuration model (gref), not the paper's MCDF active space.* Generated from the saved results by `write_reports.py`.", "",
            "## Setup", "",
            f"* Upstream `jmaxk` fix `{man['upstream_jmaxk_fix']['hash'][:10]}` (Ming Feng Gu, FAC PR #851, parent `{man['upstream_jmaxk_fix']['parent'][:10]}`) cherry-picked as "
            f"`{man['upstream_jmaxk_fix']['local_cherry_pick']['hash'][:10]}` (changed lines identical: {man['upstream_jmaxk_fix']['local_cherry_pick']['changed_lines_identical_to_upstream']}). "
            "Both builds use `-O2 -fPIC`, **no** `-ftrivial-auto-var-init=zero` (the workaround is gone). Negative control (identical flags, pre-fix source): 18 of 20 runs of a reproducer crash; "
            "post-fix 0 of 20 (`jmaxk_negative_control.json`). All 148 framework energies of the earlier sweeps are reproduced exactly by the fixed build (max |dE| = 0 eV).",
            f"* Variant B = production screened `DensityToSZ` (FAC source `{man['variant_B']['fac_source_commit'][:10]}`); variant A = B plus one line, `double mu = 0.0;` in `DensityToSZ` "
            f"(`{man['variant_A']['fac_source_commit'][:10]}`). FAC-source diff A vs B: {man['source_difference_A_vs_B']['files']} only. `radial:ee_screen` is on in both, so the screened "
            "Slater integrals and nuclear screening are identical.",
            "* Fe II, Fe III, Fe IV, existing reference-configuration lists, `gref` orbitals, mu = 0, 0.1, 0.25, same sequence and settings; 18 runs.", "",
            "## Outcome of the 18 energy runs", "",
            "* **B: 9/9 converged and validated; A: 3/9 converged (all mu = 0 controls, identical to B to 0.0 eV); the six screened A runs failed** with "
            "`No Debye bracket in RadialBound (unbound): n=3 kappa=2` (Fe II and Fe III at the first step mu = 0.05; Fe IV at mu = 0.1). Logs preserved as `run.FAILED.log`.",
            "* Therefore dE = E(B) - E(A), and dI, **cannot be measured at the published mu = 0.1 and 0.25**; it is measured below, at smaller mu, where A converges.", "",
            "### Why A fails (evidence, not proof)", "",
            "With a Coulomb direct potential the total electron potential energy `r V_tot` tends to **N-1 = 22-24** at large r (B: 0), because the nuclear term is screened but the "
            "electrons' is not. It turns repulsive at `r_c = ln(Z/(N-1))/mu`; measured 8.14 a0 (Fe II, mu = 0.01) and 6.15 a0 (Fe III, mu = 0.02), analytic 8.0 and 6.1. FAC reports no bound 3d state "
            "once that attractive region shrinks to ~4 a0 (Fe II fails from mu = 0.02, Fe III from 0.03; Fe IV survives to 0.05). So A is not a usable self-consistent model for these ions; "
            "it is a controlled artefact, not a physical alternative. (`variant_A_diagnosis/`.) Orbital-by-orbital energies were not extracted.", "",
            "## Results (B at all mu; A only at mu = 0)", "",
            an.md_table(["Transition", "mu", "IP A", "IP B", "paper", "B - paper", "B rel %", "NIST", "B - NIST", "shift B", "shift paper", "shift err B"], ip_rows), "",
            "Unscreened baseline errors (identical in A and B, so unrelated to DensityToSZ): Fe II -> III 15.5203 eV (paper 18.89, NIST 16.1992); Fe III -> IV 28.0942 eV (paper 32.93, NIST 30.651). "
            "Screening-shift errors of B against the paper: Fe II -0.60 / +0.28 eV and Fe III -0.63 / -2.31 eV at mu = 0.1 / 0.25.", "",
            "## Direct-potential effect where A converges", "",
            "Single SCF steps from the free ion, A and B, same settings (supplementary: not the published mu). With FAC's default `radial:csi`, B-A looks large "
            f"(e.g. Fe II dE = {ladd[3]['dE_Fe II']:.3f} eV and dI(Fe II) = {ladd[3]['dI_Fe II']:.3f} eV at mu = 0.01), but that is the `csi` artefact of Section 8 of "
            "`densitytosz_validation.md`. With `radial:csi = 0` in both builds the pure direct-potential effect is:", "",
            an.md_table(["mu", "dE Fe II", "dE Fe III", "dE Fe IV", "dI Fe II", "dI Fe III", "A converged II/III/IV"],
                        [[r["mu"], an.fmt(r["dE_Fe II"], 3), an.fmt(r["dE_Fe III"], 3), an.fmt(r["dE_Fe IV"], 3), an.fmt(r["dI_Fe II"], 3), an.fmt(r["dI_Fe III"], 3),
                          "/".join("y" if r[f"A_converged_{i}"] else "n" for i in ("Fe II", "Fe III", "Fe IV"))] for r in lad0]), "",
            f"The identities `dI(Fe II) = dE(Fe III) - dE(Fe II)` and `dI(Fe III) = dE(Fe IV) - dE(Fe III)` hold to < 1e-8 eV in every row. For the highly charged ions "
            f"(Fe XVII - Fe XXVI, mu = 0.1 and 0.25, both variants converge) the direct-potential part of the energy is at most {maxdirect:.3f} eV, while the electron-electron "
            "screening effect itself is -2.7 to -120.6 eV at mu = 0.1 (larger at 0.25): it comes almost entirely from the screened Slater integrals (`results/physical_checks/`). This is the variational property: the direct potential only "
            "changes the orbitals.", "",
            "## Answers", "",
            "1. **Is `DensityToSZ()` mathematically correct?** Yes. It implements `r V = e^{-mu r} int D sinh(mu r')/(mu r') + r (sinh(mu r)/(mu r)) int D e^{-mu r'}/r'` (via the stable `E(x)` form) "
            "with the Coulomb limit bit-identical to the pristine library. One declared criterion is marginally missed (deep tail of an extreme density, below).",
            "2. **Does it agree with an independent Yukawa Hartree calculation?** Yes: 1e-7..4e-7 of the peak for compact densities, 1e-8..3e-7 for valence/multishell, 1e-10..1e-8 for diffuse at mu <= 0.25, "
            "on the real grid; the floor is FAC's own quadrature and the same in the Coulomb path.",
            "3. **Is the long-range behaviour correct?** Yes: slope `-mu` to 1e-13, deviation 1e-7..1e-8 down to 1e-110, no plateau/truncation/overflow. "
            "Deep-tail relative accuracy degrades only for the extreme `2a < mu` density (1.0047e-5 against the declared 1e-5 at values > 1e-17 of the peak; the one failed pre-declared criterion).",
            "4. **Change of the Fe II, III, IV total energies?** At mu = 0 none (0.0 eV). At 0.1 and 0.25 **not measurable** (A did not converge). Where measurable (mu <= 0.03, `csi = 0`): "
            f"{min(r['dE_Fe II'] for r in lad0 if r['dE_Fe II'] is not None):.3f} to {max(r['dE_Fe II'] for r in lad0 if r['dE_Fe II'] is not None):.3f} eV (Fe II), "
            f"{min(r['dE_Fe III'] for r in lad0 if r['dE_Fe III'] is not None):.3f} to {max(r['dE_Fe III'] for r in lad0 if r['dE_Fe III'] is not None):.3f} eV (Fe III), "
            f"{min(r['dE_Fe IV'] for r in lad0 if r['dE_Fe IV'] is not None):.3f} to {max(r['dE_Fe IV'] for r in lad0 if r['dE_Fe IV'] is not None):.3f} eV (Fe IV); "
            f"for Fe XVII - XXVI at the published mu at most {maxdirect:.2f} eV.",
            "5. **Change of both IPs?** At the published mu not measurable. Where measurable: |dI| <= 0.06 eV with `csi = 0` (<= 0.03 eV for mu >= 0.01) for both ionizations; the identity holds. "
            "With the default `csi` up to ~0.4 eV, which is the `csi` artefact.",
            "6. **Does it explain a substantial part of the Fe III screening-shift discrepancy?** No evidence of that. The discrepancy of B is -0.63 eV (mu = 0.1) and -2.31 eV (0.25); the measurable direct-potential "
            "contribution is <= 0.03 eV, and in the highly charged analogues <= 0.08 eV in energy. The conclusion for mu = 0.25 itself rests on extrapolation, because A cannot be run there.",
            "7. **Better, worse, or no difference vs Deprince?** At mu = 0: identical (both 3.4 and 4.8 eV below the paper). At the published mu: A cannot be compared (no converged energies); "
            "B reproduces the screening shifts to 0.3-0.6 eV for Fe II -> III and 0.6 / 2.3 eV for Fe III -> IV. Where both exist the difference is < 0.06 eV, far below any discrepancy: **little difference**. "
            "No statement that either is \"more correct\" follows from agreement with the literature; correctness is established by the potential-level tests.",
            "8. **What remains unexplained?** (i) The unscreened IP errors (-3.37 / -4.84 eV vs paper; -0.68 / -2.56 vs NIST) and the Fe III -> IV shift errors: reduced CI space, single-configuration orbitals, "
            "no Breit/QED are candidates, none tested here. (ii) The small-mu first-order deficiency of B (up to -1.2%) tied to FAC's `csi`/`ihx` block: `csi = 0` removes it, the mechanism is not understood and "
            "has no effect at mu >= 0.1 for these ions. (iii) The exact reason A loses its 3d bound state (consistent with the repulsive tail, not proven orbital by orbital). (iv) The deep-tail accuracy for `2a < mu` densities. "
            "(v) FAC's grid-independent quadrature floor of 1e-8..1e-7.", "",
            "## Limitations", "",
            "* A cannot reach the published mu, so the A/B comparison at 0.1 and 0.25 is replaced by measurements at smaller mu plus the highly charged analogues.",
            "* The ladders are single SCF steps from the free ion; SCF-convergence jitter in E(mu) is ~0.03 eV, comparable to the small dI values.",
            "* `jmaxk` upstream fix is in both experimental builds only; the production branch has not been changed. Experiment branches are local; nothing was pushed or merged.", ""]
    (res / "experiment_summary.md").write_text("\n".join(summ))
    print("wrote densitytosz_validation.md and experiment_summary.md")
    return 0


